using System.Collections.Frozen;
using System.Numerics;
using System.Runtime.InteropServices;

namespace CatalogSvc;

/// <summary>
/// High-throughput product catalog optimized for read-heavy workloads.
/// Uses FrozenDictionary for fast lookups, a reverse index for category queries,
/// and SIMD-accelerated summation for batch price calculations.
/// </summary>
public class ProductCatalog
{
    private readonly FrozenDictionary<string, string> _categories;
    private readonly FrozenDictionary<string, double> _prices;
    private readonly FrozenDictionary<string, string[]> _productsByCategory;

    private ProductCatalog(
        FrozenDictionary<string, string> categories,
        FrozenDictionary<string, double> prices,
        FrozenDictionary<string, string[]> productsByCategory)
    {
        _categories = categories;
        _prices = prices;
        _productsByCategory = productsByCategory;
    }

    public string? GetCategory(string code)
        => _categories.TryGetValue(code, out var cat) ? cat : null;

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        // Collect matching prices into a contiguous buffer for vectorized summation
        var priceList = codes switch
        {
            ICollection<string> c => CollectPrices(codes, c.Count),
            _ => CollectPrices(codes, 0)
        };

        double total = SumVectorized(CollectionsMarshal.AsSpan(priceList));
        return (decimal)total;
    }

    public List<string> GetProductsByCategory(string category)
    {
        // O(1) reverse-index lookup instead of full scan
        if (_productsByCategory.TryGetValue(category, out var products))
            return new List<string>(products);
        return [];
    }

    private List<double> CollectPrices(IEnumerable<string> codes, int capacityHint)
    {
        var prices = new List<double>(capacityHint);
        foreach (var code in codes)
        {
            if (_prices.TryGetValue(code, out var price))
                prices.Add(price);
        }
        return prices;
    }

    /// <summary>
    /// SIMD-accelerated summation over a span of doubles.
    /// Processes Vector&lt;double&gt;-width elements per iteration.
    /// </summary>
    private static double SumVectorized(ReadOnlySpan<double> values)
    {
        if (values.IsEmpty)
            return 0.0;

        int vectorSize = Vector<double>.Count;
        int i = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= vectorSize)
        {
            var accumulator = Vector<double>.Zero;
            int limit = values.Length - (values.Length % vectorSize);

            for (; i < limit; i += vectorSize)
            {
                var vec = new Vector<double>(values.Slice(i, vectorSize));
                accumulator += vec;
            }

            double total = Vector.Sum(accumulator);

            // Handle remaining elements
            for (; i < values.Length; i++)
                total += values[i];

            return total;
        }

        // Scalar fallback
        double sum = 0.0;
        for (; i < values.Length; i++)
            sum += values[i];
        return sum;
    }

    public class Builder
    {
        private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
        private readonly Dictionary<string, double> _prices = new(StringComparer.OrdinalIgnoreCase);

        public void AddProduct(string code, string category, double price)
        {
            _categories[code] = category;
            _prices[code] = price;
        }

        /// <summary>
        /// Builds an immutable, read-optimized ProductCatalog with precomputed reverse indexes.
        /// </summary>
        public ProductCatalog Build()
        {
            var frozenCategories = _categories.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
            var frozenPrices = _prices.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);

            // Build reverse index: category -> product codes
            var reverseIndex = _categories
                .GroupBy(kvp => kvp.Value, StringComparer.OrdinalIgnoreCase)
                .ToFrozenDictionary(
                    g => g.Key,
                    g => g.Select(kvp => kvp.Key).ToArray(),
                    StringComparer.OrdinalIgnoreCase);

            return new ProductCatalog(frozenCategories, frozenPrices, reverseIndex);
        }
    }
}

